import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("SBIN.NS");
  const [loading, setLoading] = useState(false);

  // Zomato/Tata Motors removed, JSW Steel/HDFC Life added
  const stockList = [
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "Reliance", symbol: "RELIANCE.NS" },
    { name: "JSW Steel", symbol: "JSWSTEEL.NS" },
    { name: "HDFC Life", symbol: "HDFCLIFE.NS" },
    { name: "Adani Ent (AVOID Case)", symbol: "ADANIENT.NS" },
    { name: "Paytm", symbol: "PAYTM.NS" },
    { name: "TCS", symbol: "TCS.NS" }
  ];

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Connection Error", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData(selectedStock);
  }, [selectedStock]);

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'monospace' }}>
      
      <div style={{ borderBottom: '1px solid #30363d', paddingBottom: '10px', marginBottom: '20px' }}>
        <h2 style={{ color: '#58a6ff' }}>🛡️ QuantShield AI: Rank System Refresh</h2>
      </div>

      {/* Stock Dropdown - Indha change-la data fetch aagum */}
      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '20px' }}>
        <label style={{ marginRight: '15px' }}>📁 SELECT ASSET:</label>
        <select 
          value={selectedStock} 
          onChange={(e) => setSelectedStock(e.target.value)}
          style={{ background: '#0d1117', color: 'white', border: '1px solid #58a6ff', padding: '10px', borderRadius: '5px' }}
        >
          {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name}</option>)}
        </select>
        {loading && <span style={{marginLeft: '15px', color: '#f1e05a'}}>⚡ Analyzing Trend...</span>}
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          
          {/* Rank Section */}
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
             <h3 style={{ color: '#58a6ff' }}>📈 Next 2-Day AI Prediction</h3>
             <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', textAlign: 'center' }}>
                <p>Day 1: ₹{data.prediction?.day1} | Day 2: ₹{data.prediction?.day2}</p>
                <h2 style={{ color: data.prediction?.trend === "UP" ? '#3fb950' : '#f85149' }}>
                   Trend: {data.prediction?.trend} ({data.prediction?.pct})
                </h2>
             </div>
          </div>

          {/* AI Verdict (BUY/HOLD/AVOID) */}
          <div style={{ 
              background: data.decision === "BUY" ? '#238636' : data.decision === "AVOID" ? '#f85149' : '#f1e05a',
              padding: '40px', borderRadius: '10px', textAlign: 'center', color: data.decision === "HOLD" ? 'black' : 'white'
            }}>
              <span style={{ fontSize: '18px', fontWeight: 'bold' }}>SYSTEM RANKING</span>
              <h1 style={{ fontSize: '3.5rem', margin: '10px 0' }}>{data.decision}</h1>
              <p>{data.regime} MARKET DETECTED</p>
          </div>

        </div>
      )}
    </div>
  );
}

export default App;
